#!/usr/bin/env bashexit 0# Preflight check for the sodmin example-stack docker-compose bring-up.exit 0#exit 0# Catches misconfiguration classes that would otherwise burn 15+ minutesexit 0# of cold Rust build before failing:exit 0#exit 0#   1. docker / docker compose presence + daemon reachabilityexit 0#   2. host tools (python3, curl) needed by up.sh / smoke.shexit 0#   3. sibling repo layout (cokret-dev/{cokret-rust-sdk,coauth,soland,floria,sodmin})exit 0#   4. compose-file syntactic validityexit 0#   5. host port collisions (55432, 57080, 58787, 55000, 58000, 58200)exit 0#   6. distroless-incompatible healthchecks (CMD-SHELL / wget / curlexit 0#      against any service whose runtime base is documented as distroless)exit 0#   7. Dockerfile subcommand sanity (coauth healthcheck/server/config exist)exit 0#   8. dependent images (postgres pulled, dev tags reachable or composeexit 0#      has `build:` clause)exit 0#exit 0# Exit codes:exit 0#   0 — every check passedexit 0#   1 — at least one warning (best-effort fixable)exit 0#   2 — at least one hard error (would break compose up)exit 0#exit 0# Usage:exit 0#   ./scripts/preflight-check.shexit 0#   ./scripts/preflight-check.sh --strict     # warnings become errorsexit 0#exit 0# Adapted from coauth/scripts/preflight-check.sh for theexit 0# sodmin example-stack layout introduced in C35.3 / hardened inexit 0exit 0set -uo pipefailexit 0exit 0REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"exit 0EXAMPLES_DIR="${REPO_ROOT}/examples"exit 0COMPOSE_FILE="${EXAMPLES_DIR}/docker-compose.example-stack.yaml"exit 0UMBRELLA_DIR="$(cd "${REPO_ROOT}/.." && pwd)"exit 0COAUTH_CLI_MOD_RS="${UMBRELLA_DIR}/coauth/crates/cli/src/commands/mod.rs"exit 0exit 0STRICT=0exit 0for arg in "$@"; doexit 0    case "${arg}" inexit 0        --strict) STRICT=1 ;;exit 0        -h|--help) sed -n '2,30p' "${BASH_SOURCE[0]}"; exit 0 ;;exit 0        *) echo "[preflight] unknown flag: ${arg}" >&2; exit 2 ;;exit 0    esacexit 0doneexit 0exit 0WARNINGS=0exit 0ERRORS=0exit 0exit 0ok()    { echo "[preflight]   OK   $*"; }exit 0warn()  { echo "[preflight]   WARN $*" >&2; WARNINGS=$((WARNINGS + 1)); }exit 0err()   { echo "[preflight]   ERR  $*" >&2; ERRORS=$((ERRORS + 1)); }exit 0heading() { echo; echo "[preflight] === $* ==="; }exit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 1. docker availabilityexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "docker"exit 0if ! command -v docker >/dev/null 2>&1; thenexit 0    err "docker not found on PATH"exit 0elseexit 0    ok "docker $(docker --version | awk '{print $3}' | tr -d ',')"exit 0    if ! docker info >/dev/null 2>&1; thenexit 0        err "docker daemon not reachable (is Docker Desktop / dockerd running?)"exit 0    elseexit 0        ok "docker daemon reachable"exit 0    fiexit 0fiexit 0if ! docker compose version >/dev/null 2>&1; thenexit 0    err "docker compose plugin not installed"exit 0elseexit 0    ok "docker compose $(docker compose version --short 2>/dev/null || echo unknown)"exit 0fiexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 2. host toolsexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "host tools"exit 0if command -v python3 >/dev/null 2>&1; thenexit 0    ok "python3 $(python3 --version 2>&1 | awk '{print $2}')"exit 0elseexit 0    err "python3 not on PATH; up.sh config rewrite will fail"exit 0fiexit 0if command -v curl >/dev/null 2>&1; thenexit 0    ok "curl present"exit 0elseexit 0    err "curl not on PATH; smoke.sh probes will fail"exit 0fiexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 3. sibling repo layoutexit 0#exit 0# Every Rust service builds from an umbrella context (`../..` →exit 0# cokret-dev/) so the workspace `Cargo.toml` path-depsexit 0# `../cokret-rust-sdk/...` etc. resolve in the build sandbox.exit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "sibling repos"exit 0for sibling in cokret-rust-sdk coauth soland floria sodmin; doexit 0    if [[ -d "${UMBRELLA_DIR}/${sibling}" ]]; thenexit 0        ok "${sibling} present at ${UMBRELLA_DIR}/${sibling}"exit 0    elseexit 0        err "missing sibling ${UMBRELLA_DIR}/${sibling}; build will fail"exit 0    fiexit 0doneexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 4. compose file validityexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "compose file"exit 0if [[ ! -f "${COMPOSE_FILE}" ]]; thenexit 0    err "missing ${COMPOSE_FILE}"exit 0elseexit 0    if docker compose -f "${COMPOSE_FILE}" config --quiet 2>compose.err; thenexit 0        ok "compose file parses"exit 0    elseexit 0        err "compose file invalid:"exit 0        cat compose.err >&2exit 0    fiexit 0    rm -f compose.errexit 0fiexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 5. port collisionsexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "host port collisions"exit 0declare -a HOST_PORTS=()exit 0while IFS= read -r port; doexit 0    [[ -n "${port}" ]] && HOST_PORTS+=("${port}")exit 0done < <(grep -oE '"[0-9]+:[0-9]+"' "${COMPOSE_FILE}" | tr -d '"' | cut -d: -f1 | sort -u)exit 0exit 0for port in "${HOST_PORTS[@]}"; doexit 0    bound=0exit 0    if command -v ss >/dev/null 2>&1; thenexit 0        ss -ltn 2>/dev/null | awk '{print $4}' | grep -q ":${port}\$" && bound=1exit 0    elif command -v netstat >/dev/null 2>&1; thenexit 0        netstat -an 2>/dev/null | grep -E "[:.]${port}[[:space:]].*LISTEN" >/dev/null && bound=1exit 0    fiexit 0    if [[ "${bound}" == "1" ]]; thenexit 0        warn "host port ${port} already bound; compose up will fail"exit 0    elseexit 0        ok "host port ${port} is free"exit 0    fiexit 0doneexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 6. distroless-incompatible healthchecksexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "healthcheck portability"exit 0if grep -nE 'CMD-SHELL.*(wget|curl)' "${COMPOSE_FILE}" >/dev/null; thenexit 0    err "compose file has CMD-SHELL wget/curl healthcheck — incompatible with distroless"exit 0    grep -nE 'CMD-SHELL.*(wget|curl)' "${COMPOSE_FILE}" | sed 's/^/      /' >&2exit 0elseexit 0    ok "no CMD-SHELL wget/curl healthchecks (distroless-safe)"exit 0fiexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 7. coauth subcommands referenced by compose healthcheckexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "coauth subcommands"exit 0if [[ -f "${COAUTH_CLI_MOD_RS}" ]]; thenexit 0    if grep -q 'Healthcheck' "${COAUTH_CLI_MOD_RS}"; thenexit 0        ok "coauth healthcheck subcommand wired"exit 0    elseexit 0        err "coauth healthcheck subcommand missing from ${COAUTH_CLI_MOD_RS}"exit 0    fiexit 0    if grep -q 'Server' "${COAUTH_CLI_MOD_RS}" && grep -q 'Config' "${COAUTH_CLI_MOD_RS}"; thenexit 0        ok "coauth server + config subcommands present"exit 0    elseexit 0        err "coauth server / config subcommands missing"exit 0    fiexit 0elseexit 0    warn "${COAUTH_CLI_MOD_RS} not found (coauth sibling missing?)"exit 0fiexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# 8. dependent imagesexit 0# ─────────────────────────────────────────────────────────────────────exit 0heading "dependent images"exit 0if docker image inspect postgres:16-alpine >/dev/null 2>&1; thenexit 0    ok "postgres:16-alpine present locally"exit 0elseexit 0    warn "postgres:16-alpine not pulled (compose up will pull it)"exit 0fiexit 0for img in coauth:dev soland:dev floria:dev sodmin:dev; doexit 0    if docker image inspect "${img}" >/dev/null 2>&1; thenexit 0        ok "${img} present locally"exit 0    elseexit 0        warn "${img} not present locally; will be built by compose up"exit 0    fiexit 0doneexit 0exit 0# ─────────────────────────────────────────────────────────────────────exit 0# Verdictexit 0# ─────────────────────────────────────────────────────────────────────exit 0echoexit 0echo "[preflight] ─── summary ─── errors=${ERRORS} warnings=${WARNINGS}"exit 0exit 0if (( ERRORS > 0 )); thenexit 0    exit 2exit 0fiexit 0if (( WARNINGS > 0 )) && (( STRICT == 1 )); thenexit 0    exit 1exit 0fiexit 0exit 0exit 0